// Builds src/data/vocab.generated.ts, which the app loads into SQLite on first launch
// (and again whenever the lists change).
//
//   npm run vocab
//
// Words come from two files, in this order (line order = frequency rank):
//   data/vocab.psv            hand-written starter words (edit this one)
//   data/vocab-frequency.psv  the top 10,000 conversational words, generated by
//                             scripts/import-jmdict.mjs (don't edit by hand)
// A word already in vocab.psv is skipped in the frequency list, so the hand-written
// version wins and its id (and your progress on it) never changes.
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'src', 'data', 'vocab.generated.ts');

const TYPES = new Set([
  'noun', 'pronoun', 'verb-ru', 'verb-u', 'verb-irr',
  'adj-i', 'adj-na', 'adj-pre', 'adverb', 'expression', 'question',
  'particle', 'conjunction', 'counter', 'number',
]);

const words = [];
const seen = new Set();
const kanaOnly = new Map(); // kana -> has a version with kanji / without
const errors = [];

function readWords(file, { strict }) {
  const path = join(root, 'data', file);
  if (!existsSync(path)) return 0;
  let added = 0;
  readFileSync(path, 'utf8').split(/\r?\n/).forEach((line, i) => {
    const t = line.trim();
    if (!t || t.startsWith('#')) return;
    const where = `${file} line ${i + 1}`;
    const parts = t.split('|').map((p) => p.trim());
    if (parts.length !== 5) {
      errors.push(`${where}: expected 5 fields, got ${parts.length}`);
      return;
    }
    const [rawKanji, kana, meaning, type, context] = parts;
    const kanji = rawKanji === kana ? '' : rawKanji;
    if (!kana || !meaning || !context) errors.push(`${where}: kana, meaning and context are required`);
    if (!TYPES.has(type)) errors.push(`${where}: unknown type "${type}"`);
    const key = `${kanji}|${kana}`;
    // The same word written with and without kanji (分かる / わかる) counts as a duplicate.
    const sameWord = seen.has(key) || (kanji === '' && kanaOnly.has(kana)) || (kanji !== '' && kanaOnly.get(kana) === 'kana');
    if (sameWord) {
      if (strict) errors.push(`${where}: duplicate word ${kanji || kana}`);
      return;
    }
    seen.add(key);
    if (!kanaOnly.has(kana)) kanaOnly.set(kana, kanji ? 'kanji' : 'kana');
    words.push([kanji, kana, meaning, type, context]);
    added++;
  });
  return added;
}

const starter = readWords('vocab.psv', { strict: true });
const frequent = readWords('vocab-frequency.psv', { strict: false });

// ---- sentences: japanese | kana | english | word=surface,word=surface
const sentPath = join(root, 'data', 'sentences.psv');
const byWritten = new Map();
words.forEach((w, i) => {
  const k = w[0] || w[1];
  if (!byWritten.has(k)) byWritten.set(k, i + 1); // starter words win
});
const sentences = [];
readFileSync(sentPath, 'utf8').split(/\r?\n/).forEach((line, i) => {
  const t = line.trim();
  if (!t || t.startsWith('#')) return;
  const parts = t.split('|').map((p) => p.trim());
  const where = `sentences.psv line ${i + 1}`;
  if (parts.length !== 4) {
    errors.push(`${where}: expected 4 fields, got ${parts.length}`);
    return;
  }
  const [jp, kana, en, targetsRaw] = parts;
  const targets = [];
  for (const pair of targetsRaw.split(',').map((x) => x.trim()).filter(Boolean)) {
    const [word, surface] = pair.split('=').map((x) => x.trim());
    const id = byWritten.get(word);
    if (!id) errors.push(`${where}: "${word}" is not in vocab.psv`);
    else if (!surface || !jp.includes(surface)) errors.push(`${where}: "${surface}" not found in the sentence`);
    else targets.push([id, surface]);
  }
  if (!targets.length) errors.push(`${where}: needs at least one target word`);
  sentences.push([jp, kana, en, targets]);
});

if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}

const version = createHash('sha1').update(JSON.stringify([words, sentences])).digest('hex').slice(0, 12);
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// AUTO-GENERATED by scripts/build-vocab.mjs from data/vocab.psv. Do not edit by hand.\n` +
    `// Row format: [kanji, kana, meaning, type, context]; array index + 1 = frequency rank.\n` +
    `export const VOCAB_VERSION = '${version}';\n` +
    `export const VOCAB: readonly (readonly [string, string, string, string, string])[] = ${JSON.stringify(words, null, 0).replace(/\],\[/g, '],\n  [')};\n` +
    `// Row format: [japanese, kana, english, [[wordId, surface], ...]]\n` +
    `export const SENTENCES: readonly (readonly [string, string, string, readonly (readonly [number, string])[]])[] = ${JSON.stringify(sentences, null, 0).replace(/\]\]\],\[/g, ']]],\n  [')};\n`,
);
console.log(`Wrote ${words.length} words (${starter} starter + ${frequent} from the frequency list) and ${sentences.length} sentences (version ${version})`);
